(6174611, 911073, 15711, '<td valign="top">Holy Smokes!! <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=27133" rel="nofollow" target="_blank">judi</a> is this yours???  Absolutely fabulous.  The contre jour and silhouettes.  WOWZA 10 10 10</td>', 'Holy Smokes!!  judi is this yours???  Absolutely fabulous.  The contre jour and silhouettes.  WOWZA 10 10 10', '2010-09-29 10:31:59.000000', NULL, 1),
(6174614, 911706, 15711, '<td valign="top">Perfect title as the shot is quite painterly.  Lovely perspective and wide angle focus.</td>', 'Perfect title as the shot is quite painterly.  Lovely perspective and wide angle focus.', '2010-09-29 10:32:55.000000', NULL, 1),
(6174615, 911819, 15711, '<td valign="top">I really like the swish of the tail.  Lovely low key approach.</td>', 'I really like the swish of the tail.  Lovely low key approach.', '2010-09-29 10:33:21.000000', NULL, 1),
(6174617, 911012, 15711, '<td valign="top">Every time I see these horses I think of the late American singer, Peggy Lee.  She always wore her hair over one eye. LOL</td>', 'Every time I see these horses I think of the late American singer, Peggy Lee.  She always wore her hair over one eye. LOL', '2010-09-29 10:34:01.000000', NULL, 1),
(6174619, 911102, 15711, '<td valign="top">We rarely see rural settings in BW.  LOVE the trees.  Artfully presented. 8</td>', 'We rarely see rural settings in BW.  LOVE the trees.  Artfully presented. 8', '2010-09-29 10:34:44.000000', NULL, 1),
(6174622, 911733, 15711, '<td valign="top">Lovely.  I really like that you chose to do this in BW.  I like the perspective too.</td>', 'Lovely.  I really like that you chose to do this in BW.  I like the perspective too.', '2010-09-29 10:35:37.000000', NULL, 1),
(6174626, 911791, 15711, '<td valign="top">I love this LOL  I didn''t realize that sheep (goats?) had long tails.  Terrific shot.</td>', 'I love this LOL  I didn''t realize that sheep (goats?) had long tails.  Terrific shot.', '2010-09-29 10:36:49.000000', NULL, 1),
(6174681, 910827, 121248, '<td valign="top">Very nice, this so screams country</td>', 'Very nice, this so screams country', '2010-09-29 11:04:10.000000', NULL, 1),
(6174694, 911825, 39679, '<td valign="top">This is a really nice shot but, understanding that you don''t control the weather (and if I''m wrong with that, please give me a call for an exciting business opportunity), I think this shot would have been truly outstanding shot with dappled or intermittent sunlight.</td>', 'This is a really nice shot but, understanding that you don''t control the weather (and if I''m wrong with that, please give me a call for an exciting business opportunity), I think this shot would have been truly outstanding shot with dappled or intermittent sunlight.', '2010-09-29 11:15:48.000000', NULL, 1),
(6174697, 911427, 39679, '<td valign="top">I love the way you composed this shot. The mountains carry a lot of weight in this shot so using more of the farmland balanced them really well.  Nice job.</td>', 'I love the way you composed this shot. The mountains carry a lot of weight in this shot so using more of the farmland balanced them really well.  Nice job.', '2010-09-29 11:18:01.000000', NULL, 1),
(6174700, 911018, 39679, '<td valign="top">Choosing to make this shot black and white was a great idea. I immediately found this shot interesting because of the contrast, even before I realized what the object was.</td>', 'Choosing to make this shot black and white was a great idea. I immediately found this shot interesting because of the contrast, even before I realized what the object was.', '2010-09-29 11:20:00.000000', NULL, 1),
(6174702, 911310, 39679, '<td valign="top">This is an interesting shot but the colors seem just a little washed out to me. This would have been a great time to pull out a polarizer.</td>', 'This is an interesting shot but the colors seem just a little washed out to me. This would have been a great time to pull out a polarizer.', '2010-09-29 11:22:29.000000', NULL, 1),
(6174704, 911387, 39679, '<td valign="top">I''m not sure why you chose to use black and white in this.  With so little contrast the road seems to be lost. I would imagine the color image would have helped to make the road stand out more.</td>', 'I''m not sure why you chose to use black and white in this.  With so little contrast the road seems to be lost. I would imagine the color image would have helped to make the road stand out more.', '2010-09-29 11:23:56.000000', NULL, 1),
(6174723, 911465, 10785, '<td valign="top">That country boy needs some sun!!! Get him out in the fields and work him a bit... lol! Very nice capture freezing the motion and getting that great boyish expression! The surrounding landscape is so warm and well it by the sun, that the pale boy is a huge contrast to that.</td>', 'That country boy needs some sun!!! Get him out in the fields and work him a bit... lol! Very nice capture freezing the motion and getting that great boyish expression! The surrounding landscape is so warm and well it by the sun, that the pale boy is a huge contrast to that.', '2010-09-29 11:41:19.000000', NULL, 1),
(6174742, 911018, 99263, '<td valign="top">What are those? Leather wine gourds? Very nice dof and lighting.</td>', 'What are those? Leather wine gourds? Very nice dof and lighting.', '2010-09-29 11:50:14.000000', NULL, 1),
(6174750, 911819, 99263, '<td valign="top">Superb horse portrait. I love the smooth tones and the light. 8</td>', 'Superb horse portrait. I love the smooth tones and the light. 8', '2010-09-29 11:53:49.000000', NULL, 1),
(6174751, 911334, 99263, '<td valign="top">Eeekkk....scary!</td>', 'Eeekkk....scary!', '2010-09-29 11:54:18.000000', NULL, 1),
(6174755, 911874, 10785, '<td valign="top">Good shot... needs a person.</td>', 'Good shot... needs a person.', '2010-09-29 11:56:33.000000', NULL, 1),
(6174770, 911427, 99263, '<td valign="top">Stunning vista with lots of depth. Those snow capped mountain peaks are absolutely beautiful and the rural landscape in the foreground is so inviting. Your processing and the fine detail really makes it complete. One of my favorites for a ribbon here. 9</td>', 'Stunning vista with lots of depth. Those snow capped mountain peaks are absolutely beautiful and the rural landscape in the foreground is so inviting. Your processing and the fine detail really makes it complete. One of my favorites for a ribbon here. 9', '2010-09-29 12:05:10.000000', NULL, 1),
(6174776, 911791, 99263, '<td valign="top">So cool and so well processed with superb contrast and detail. Excellent and one of my favorites for one of the ribbons here. 9</td>', 'So cool and so well processed with superb contrast and detail. Excellent and one of my favorites for one of the ribbons here. 9', '2010-09-29 12:09:43.000000', NULL, 1),
(6174777, 911340, 10785, '<td valign="top">Such a cute and wonderful shot. Love the smirk on her face because she is leaning on the steering wheel. The only issue with this shot is that it is overexposed a bit leaving the skin around her right eye blank and her skin very pale and without detail overall. A half or one stop down would fix that and leave you with a black steering wheel instead of a grey one. Otherwise this shot is just priceless!</td>', 'Such a cute and wonderful shot. Love the smirk on her face because she is leaning on the steering wheel. The only issue with this shot is that it is overexposed a bit leaving the skin around her right eye blank and her skin very pale and without detail overall. A half or one stop down would fix that and leave you with a black steering wheel instead of a grey one. Otherwise this shot is just priceless!', '2010-09-29 12:09:49.000000', NULL, 1),
(6174783, 911523, 99263, '<td valign="top">Wonderful capture. Lovely light. Very nice processing. It''s a simple scene but breathes lots of quite beauty. Those mountains in the background are so nice. 8</td>', 'Wonderful capture. Lovely light. Very nice processing. It''s a simple scene but breathes lots of quite beauty. Those mountains in the background are so nice. 8', '2010-09-29 12:15:10.000000', NULL, 1),
(6174789, 911073, 99263, '<td valign="top">Very very nice. The  back light creates a stunning silhouetted image. Love the steam from the horses mouth in the cold morning air. Lovely light...a really wonderful picture. One of my favorites for the Blue ribbon here. 10</td>', 'Very very nice. The  back light creates a stunning silhouetted image. Love the steam from the horses mouth in the cold morning air. Lovely light...a really wonderful picture. One of my favorites for the Blue ribbon here. 10', '2010-09-29 12:20:02.000000', NULL, 1),
(6174790, 911404, 99263, '<td valign="top">Beautiful the way the mist shrouds the horse and the background. Gives it a dreamlike feeling. Nice soft muted colors. 7</td>', 'Beautiful the way the mist shrouds the horse and the background. Gives it a dreamlike feeling. Nice soft muted colors. 7', '2010-09-29 12:20:33.000000', NULL, 1),
(6174792, 910816, 99263, '<td valign="top">Very country like feel. A stately country home and a noble horse.Very nice image. 7</td>', 'Very country like feel. A stately country home and a noble horse.Very nice image. 7', '2010-09-29 12:20:38.000000', NULL, 1),
(6174793, 911825, 99263, '<td valign="top">Beautiful view with stunning autumn colors. 8</td>', 'Beautiful view with stunning autumn colors. 8', '2010-09-29 12:20:47.000000', NULL, 1),
(6174794, 911126, 99263, '<td valign="top">Wonderful cow shot. I really like the processing in black and white. Nice and contrasty. 7</td>', 'Wonderful cow shot. I really like the processing in black and white. Nice and contrasty. 7', '2010-09-29 12:20:55.000000', NULL, 1),
(6174795, 911287, 99263, '<td valign="top">Striking minimalism. Really cool. 7</td>', 'Striking minimalism. Really cool. 7', '2010-09-29 12:21:00.000000', NULL, 1),
(6174796, 911809, 99263, '<td valign="top">Very different and almost surrealistically abstract in some way if that''s possible. I like the objects presented on 3 different levels or tiers and then the people in the background. Very cool. 7</td>', 'Very different and almost surrealistically abstract in some way if that''s possible. I like the objects presented on 3 different levels or tiers and then the people in the background. Very cool. 7', '2010-09-29 12:21:10.000000', NULL, 1),
