(6175815, 911073, 113419, '<td valign="top">love this silhouette; good tones; nice angle; looks like a cool crisp fall morning</td>', 'love this silhouette; good tones; nice angle; looks like a cool crisp fall morning', '2010-09-30 12:30:42.000000', NULL, 1),
