(6178391, 911368, 121916, '<td valign="top">I like the overall feeling of this.  The editing appears natural.  My only niggle is the OOF weed on the right of the barn.  I find it slightly distracting, but love the composition of the image.</td>', 'I like the overall feeling of this.  The editing appears natural.  My only niggle is the OOF weed on the right of the barn.  I find it slightly distracting, but love the composition of the image.', '2010-10-02 17:10:48.000000', NULL, 1),
(6178392, 911465, 121916, '<td valign="top">Great action shot....the joy of childhood. Beautifully rendered colors.</td>', 'Great action shot....the joy of childhood. Beautifully rendered colors.', '2010-10-02 17:10:53.000000', NULL, 1),
(6178393, 911415, 121916, '<td valign="top">Good straight forward portrait.</td>', 'Good straight forward portrait.', '2010-10-02 17:10:59.000000', NULL, 1),
(6178394, 911073, 121916, '<td valign="top">Beautiful rim lighting.  I wish the horse''s neck was as dark as the rest.</td>', 'Beautiful rim lighting.  I wish the horse''s neck was as dark as the rest.', '2010-10-02 17:11:04.000000', NULL, 1),
(6178395, 910817, 121916, '<td valign="top">Very intense and dramatic colors.  Beautiful landscape.</td>', 'Very intense and dramatic colors.  Beautiful landscape.', '2010-10-02 17:11:17.000000', NULL, 1),
