(6182867, 911001, 102278, '<td valign="top">I thought this was great. Got an 8 from me.</td>', 'I thought this was great. Got an 8 from me.', '2010-10-06 08:05:40.000000', NULL, 0),
(6182869, 911102, 115676, '<td valign="top">Congrats on the well deserved ribbon. Love it!</td>', 'Congrats on the well deserved ribbon. Love it!', '2010-10-06 08:06:28.000000', NULL, 0),
(6182871, 911336, 114934, '<td valign="top">Very uninteresting. If you tried to move the tractor off center a little more it might have worked a bit better - and zoomed in a bit more to the farmer... and lose the fence in the foreground and did more to keep the sky from washing out so much. Also - there is more to life in farming then some guy running a tractor- looks like a lazy shot where you just got out of the car and snapped off a picture and tried to make it look artsy with a little Photoshop work - maybe it might have rated a 3 or so - but a 2 is the best I could give this.  Pretty bad photo actually. Sorry - just how I feel.</td>', 'Very uninteresting. If you tried to move the tractor off center a little more it might have worked a bit better - and zoomed in a bit more to the farmer... and lose the fence in the foreground and did more to keep the sky from washing out so much. Also - there is more to life in farming then some guy running a tractor- looks like a lazy shot where you just got out of the car and snapped off a picture and tried to make it look artsy with a little Photoshop work - maybe it might have rated a 3 or so - but a 2 is the best I could give this.  Pretty bad photo actually. Sorry - just how I feel.', '2010-10-06 08:08:19.000000', NULL, 0),
(6182880, 911102, 60047, '<td valign="top">Nice work, Steve.</td>', 'Nice work, Steve.', '2010-10-06 08:20:52.000000', NULL, 0),
(6182883, 911803, 33361, '<td valign="top">I gave this an 8 - it definitely says country life here in Texas!!</td>', 'I gave this an 8 - it definitely says country life here in Texas!!', '2010-10-06 08:27:55.000000', NULL, 0),
(6182909, 911073, 61012, '<td valign="top">Congrats on the blue, proud to make it into the top three along with this shot.</td>', 'Congrats on the blue, proud to make it into the top three along with this shot.', '2010-10-06 09:05:15.000000', NULL, 0),
(6182910, 911102, 61012, '<td valign="top">Very nice Steve. Congrats on the Yellow! Awesome B&amp;W conversion and I really like the interaction of the trees and the border.</td>', 'Very nice Steve. Congrats on the Yellow! Awesome B&W conversion and I really like the interaction of the trees and the border.', '2010-10-06 09:06:58.000000', NULL, 0),
(6182914, 911102, 15711, '<td valign="top">Well done, my friend!!  Yippee for you.</td>', 'Well done, my friend!!  Yippee for you.', '2010-10-06 09:16:50.000000', NULL, 0),
